CREATE TABLE tenants (
  id                        TEXT PRIMARY KEY,
  slug                      TEXT NOT NULL UNIQUE,
  name                      TEXT NOT NULL,
  phone                     TEXT,
  address                   TEXT,
  city                      TEXT,
  brand_color               TEXT NOT NULL DEFAULT '#3f6f68',
  logo_url                  TEXT,
  utc_offset_minutes        INTEGER NOT NULL DEFAULT -300,
  slot_interval_minutes     INTEGER NOT NULL DEFAULT 30,
  min_booking_notice_hours  INTEGER NOT NULL DEFAULT 2,
  booking_window_days       INTEGER NOT NULL DEFAULT 30,
  reactivation_months       INTEGER NOT NULL DEFAULT 6,
  online_booking_enabled    INTEGER NOT NULL DEFAULT 1,
  close_on_holidays         INTEGER NOT NULL DEFAULT 1,
  privacy_policy_version    TEXT NOT NULL DEFAULT '1',
  is_showcase               INTEGER NOT NULL DEFAULT 0,
  created_at                TEXT NOT NULL
, whatsapp_number TEXT, whatsapp_reminder_template TEXT, online_verification_mode TEXT NOT NULL DEFAULT 'ninguna'
  CHECK (online_verification_mode IN ('ninguna', 'whatsapp')), verification_window_minutes INTEGER NOT NULL DEFAULT 60
  CHECK (verification_window_minutes BETWEEN 10 AND 1440), max_pending_online_per_patient INTEGER NOT NULL DEFAULT 2
  CHECK (max_pending_online_per_patient BETWEEN 1 AND 20), auto_release_hours INTEGER NOT NULL DEFAULT 0
  CHECK (auto_release_hours BETWEEN 0 AND 72), payment_window_minutes INTEGER NOT NULL DEFAULT 30
  CHECK (payment_window_minutes BETWEEN 20 AND 120), paid_until TEXT, monthly_price INTEGER NOT NULL DEFAULT 0, grace_days INTEGER NOT NULL DEFAULT 3, billing_mode TEXT NOT NULL DEFAULT 'auto', owner_notes TEXT, plan_id TEXT NOT NULL DEFAULT 'completo', addon_modules TEXT NOT NULL DEFAULT '', extra_professionals INTEGER NOT NULL DEFAULT 0, extra_users INTEGER NOT NULL DEFAULT 0, custom_price INTEGER, enabled_modules TEXT NOT NULL DEFAULT 'finanzas,inventario,facturacion,auditoria', max_professionals INTEGER NOT NULL DEFAULT 5, max_users INTEGER NOT NULL DEFAULT 12, pending_plan TEXT, on_trial INTEGER NOT NULL DEFAULT 0, signup_source TEXT NOT NULL DEFAULT 'dueno', demo_expires_at TEXT, contact_name TEXT, contact_email TEXT, contact_phone TEXT, converted_tenant_id TEXT);
