CREATE TABLE time_blocks (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL REFERENCES tenants(id),
  professional_id  TEXT REFERENCES professionals(id) ON DELETE CASCADE,
  start_at         TEXT NOT NULL,
  end_at           TEXT NOT NULL,
  reason           TEXT,
  created_by       TEXT,
  created_at       TEXT NOT NULL,
  CHECK (start_at < end_at)
);
CREATE TABLE services (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants(id),
  code                TEXT NOT NULL,
  name                TEXT NOT NULL,
  category            TEXT,
  item_type           TEXT NOT NULL DEFAULT 'servicio' CHECK (item_type IN ('servicio', 'insumo')),
  price               INTEGER NOT NULL CHECK (price >= 0),
  duration_minutes    INTEGER NOT NULL DEFAULT 30 CHECK (duration_minutes BETWEEN 5 AND 480),
  tax_rate_bps        INTEGER NOT NULL DEFAULT 0 CHECK (tax_rate_bps BETWEEN 0 AND 10000),
  is_bookable_online  INTEGER NOT NULL DEFAULT 1,
  is_active           INTEGER NOT NULL DEFAULT 1,
  created_at          TEXT NOT NULL, prepayment_mode TEXT NOT NULL DEFAULT 'ninguno'
  CHECK (prepayment_mode IN ('ninguno', 'porcentaje', 'valor')), prepayment_value INTEGER NOT NULL DEFAULT 0
  CHECK (prepayment_value >= 0),
  UNIQUE (tenant_id, code)
);
