CREATE TABLE appointments (
  id                   TEXT PRIMARY KEY,
  tenant_id            TEXT NOT NULL REFERENCES tenants(id),
  patient_id           TEXT NOT NULL REFERENCES patients(id),
  professional_id      TEXT NOT NULL REFERENCES professionals(id),
  service_id           TEXT NOT NULL REFERENCES services(id),
  start_at             TEXT NOT NULL,
  end_at               TEXT NOT NULL,
  status               TEXT NOT NULL DEFAULT 'pendiente'
                         CHECK (status IN ('pendiente', 'confirmada', 'atendida', 'no_asistio', 'cancelada')),
  source               TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('online', 'manual')),
  price                INTEGER NOT NULL DEFAULT 0,
  notes                TEXT,
  recurrence_group_id  TEXT,
  reminder_sent_at     TEXT,
  confirmed_at         TEXT,
  cancelled_at         TEXT,
  cancel_reason        TEXT,
  created_by           TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL, hold_reason TEXT
  CHECK (hold_reason IS NULL OR hold_reason IN ('pago', 'verificacion', 'confirmacion')), hold_expires_at TEXT, verification_code TEXT, prepayment_amount INTEGER NOT NULL DEFAULT 0,
  CHECK (start_at < end_at)
);
