CREATE TABLE waitlist_entries (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL REFERENCES tenants(id),
  patient_id       TEXT NOT NULL REFERENCES patients(id),
  service_id       TEXT REFERENCES services(id),
  professional_id  TEXT REFERENCES professionals(id),
  notes            TEXT,
  status           TEXT NOT NULL DEFAULT 'activa' CHECK (status IN ('activa', 'resuelta')),
  created_at       TEXT NOT NULL
);
INSERT INTO "waitlist_entries" ("id","tenant_id","patient_id","service_id","professional_id","notes","status","created_at") VALUES('2009f758-d31e-49b7-9427-6360167635d1','b1dd2246-2160-4568-a63b-266e95a540f9','9eb9b754-9bbc-4912-be60-26313824c3cb','ae4da1c9-8df5-4682-9fb1-6be2ee86dc87',NULL,'Prefiere jornada de la tarde','activa','2026-10-14T01:16:52.250Z');
CREATE TABLE charges (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id),
  patient_id      TEXT NOT NULL REFERENCES patients(id),
  appointment_id  TEXT UNIQUE REFERENCES appointments(id),
  service_id      TEXT REFERENCES services(id),
  description     TEXT NOT NULL,
  quantity        INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
  amount          INTEGER NOT NULL CHECK (amount > 0),
  status          TEXT NOT NULL DEFAULT 'activo' CHECK (status IN ('activo', 'anulado')),
  void_reason     TEXT,
  voided_by       TEXT,
  voided_at       TEXT,
  created_by      TEXT,
  created_at      TEXT NOT NULL
);
