CREATE TABLE payments (
  id              TEXT PRIMARY KEY,
  tenant_id       TEXT NOT NULL REFERENCES tenants(id),
  patient_id      TEXT NOT NULL REFERENCES patients(id),
  receipt_number  INTEGER NOT NULL,
  amount          INTEGER NOT NULL CHECK (amount > 0),
  method          TEXT NOT NULL CHECK (method IN ('efectivo', 'transferencia', 'nequi', 'daviplata', 'tarjeta', 'otro')),
  reference       TEXT,
  notes           TEXT,
  status          TEXT NOT NULL DEFAULT 'activo' CHECK (status IN ('activo', 'anulado')),
  void_reason     TEXT,
  voided_by       TEXT,
  voided_at       TEXT,
  created_by      TEXT,
  created_at      TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'caja' CHECK (source IN ('caja', 'wompi')), external_id TEXT, appointment_id TEXT REFERENCES appointments(id),
  UNIQUE (tenant_id, receipt_number)
);
