CREATE TABLE payment_gateways (
  tenant_id             TEXT PRIMARY KEY REFERENCES tenants(id),
  provider              TEXT NOT NULL DEFAULT 'wompi' CHECK (provider IN ('wompi')),
  environment           TEXT NOT NULL CHECK (environment IN ('sandbox', 'production')),
  public_key            TEXT NOT NULL,
  integrity_secret_enc  TEXT NOT NULL,
  events_secret_enc     TEXT NOT NULL,
  webhook_key           TEXT NOT NULL UNIQUE,
  is_enabled            INTEGER NOT NULL DEFAULT 0,
  policy_text           TEXT,
  last_verified_at      TEXT,
  last_event_at         TEXT,
  updated_by            TEXT,
  updated_at            TEXT NOT NULL
);
CREATE TABLE payment_intents (
  id                    TEXT PRIMARY KEY,
  tenant_id             TEXT NOT NULL REFERENCES tenants(id),
  appointment_id        TEXT NOT NULL REFERENCES appointments(id),
  patient_id            TEXT NOT NULL REFERENCES patients(id),
  reference             TEXT NOT NULL UNIQUE,
  amount_in_cents       INTEGER NOT NULL CHECK (amount_in_cents > 0),
  currency              TEXT NOT NULL DEFAULT 'COP' CHECK (currency = 'COP'),
  environment           TEXT NOT NULL CHECK (environment IN ('sandbox', 'production')),
  status                TEXT NOT NULL DEFAULT 'PENDING'
                          CHECK (status IN ('PENDING', 'APPROVED', 'DECLINED', 'VOIDED', 'ERROR', 'EXPIRED')),
  outcome               TEXT CHECK (outcome IS NULL OR outcome IN ('cita_confirmada', 'sin_cupo', 'pago_duplicado', 'anulado_en_wompi', 'monto_no_coincide')),
  needs_attention       INTEGER NOT NULL DEFAULT 0,
  attention_resolved_at TEXT,
  attention_resolved_by TEXT,
  wompi_transaction_id  TEXT,
  payment_method_type   TEXT,
  payment_id            TEXT REFERENCES payments(id),
  checkout_expires_at   TEXT NOT NULL,
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);
CREATE TABLE suppliers (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id),
  name          TEXT NOT NULL,
  nit           TEXT,
  phone         TEXT,
  email         TEXT,
  contact_name  TEXT,
  notes         TEXT,
  is_active     INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT NOT NULL
);
INSERT INTO "suppliers" ("id","tenant_id","name","nit","phone","email","contact_name","notes","is_active","created_at") VALUES('17303698-3133-4d30-93f2-83c44b29440b','b1dd2246-2160-4568-a63b-266e95a540f9','Depósito Dental Andino S.A.S.','900555123','+576044440000',NULL,'Carolina Mejía',NULL,1,'2026-10-14T01:16:52.510Z');
CREATE TABLE supplies (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants(id),
  code        TEXT NOT NULL,
  name        TEXT NOT NULL,
  unit        TEXT NOT NULL DEFAULT 'unidad',
  min_stock   REAL NOT NULL DEFAULT 0 CHECK (min_stock >= 0),
  
  avg_cost    REAL NOT NULL DEFAULT 0 CHECK (avg_cost >= 0),
  is_active   INTEGER NOT NULL DEFAULT 1,
  created_at  TEXT NOT NULL,
  UNIQUE (tenant_id, code)
);
