CREATE TABLE supplier_item_links (
  tenant_id      TEXT NOT NULL REFERENCES tenants(id),
  supplier_id    TEXT NOT NULL REFERENCES suppliers(id),
  supplier_code  TEXT NOT NULL,
  supply_id      TEXT NOT NULL REFERENCES supplies(id),
  conversion_factor REAL NOT NULL DEFAULT 1,
  PRIMARY KEY (tenant_id, supplier_id, supplier_code)
);
CREATE TABLE einvoice_settings (
  tenant_id           TEXT PRIMARY KEY REFERENCES tenants(id),
  provider            TEXT NOT NULL DEFAULT 'externo' CHECK (provider IN ('externo', 'factus', 'webhook')),
  environment         TEXT NOT NULL DEFAULT 'pruebas' CHECK (environment IN ('pruebas', 'produccion')),
  
  credentials_enc     TEXT,
  
  public_config       TEXT NOT NULL DEFAULT '{}',
  token_enc           TEXT,
  token_expires_at    TEXT,
  is_enabled          INTEGER NOT NULL DEFAULT 0,
  last_verified_at    TEXT,
  updated_by          TEXT,
  updated_at          TEXT NOT NULL
);
CREATE TABLE sales_invoices (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL REFERENCES tenants(id),
  patient_id       TEXT NOT NULL REFERENCES patients(id),
  reference_code   TEXT NOT NULL,
  provider         TEXT NOT NULL CHECK (provider IN ('externo', 'factus', 'webhook')),
  status           TEXT NOT NULL CHECK (status IN ('pendiente', 'emitida', 'rechazada', 'anulada')),
  number           TEXT,
  cufe             TEXT,
  qr_url           TEXT,
  public_url       TEXT,
  customer         TEXT NOT NULL, 
  payment_form     TEXT NOT NULL CHECK (payment_form IN ('contado', 'credito')),
  payment_method   TEXT NOT NULL,
  due_date         TEXT,
  observation      TEXT,
  subtotal         INTEGER NOT NULL CHECK (subtotal >= 0),
  tax_total        INTEGER NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
  total            INTEGER NOT NULL CHECK (total > 0),
  last_error       TEXT,
  attempts         INTEGER NOT NULL DEFAULT 0,
  void_reason      TEXT,
  credit_note_ref  TEXT,
  created_by       TEXT REFERENCES users(id),
  created_at       TEXT NOT NULL,
  issued_at        TEXT,
  UNIQUE (tenant_id, reference_code)
);
CREATE TABLE sales_invoice_lines (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id),
  invoice_id    TEXT NOT NULL REFERENCES sales_invoices(id),
  charge_id     TEXT NOT NULL REFERENCES charges(id),
  code          TEXT NOT NULL,
  description   TEXT NOT NULL,
  quantity      INTEGER NOT NULL CHECK (quantity > 0),
  unit_price    INTEGER NOT NULL CHECK (unit_price >= 0),
  tax_rate_bps  INTEGER NOT NULL DEFAULT 0,
  line_total    INTEGER NOT NULL CHECK (line_total >= 0),
  
  is_active     INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE subscription_checkouts (
  reference     TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants(id),
  amount        INTEGER NOT NULL CHECK (amount > 0),
  months        INTEGER NOT NULL,
  status        TEXT NOT NULL DEFAULT 'pendiente' CHECK (status IN ('pendiente', 'aprobado', 'rechazado')),
  transaction_id TEXT,
  created_at    TEXT NOT NULL
, kind TEXT NOT NULL DEFAULT 'renovacion', plan_snapshot TEXT);
CREATE TABLE platform_settings (
  id                    INTEGER PRIMARY KEY CHECK (id = 1),
  owner_name            TEXT,
  owner_whatsapp        TEXT,
  payment_instructions  TEXT,
  default_monthly_price INTEGER NOT NULL DEFAULT 0,
  default_grace_days    INTEGER NOT NULL DEFAULT 3,
  default_trial_days    INTEGER NOT NULL DEFAULT 15,
  wompi_environment     TEXT CHECK (wompi_environment IN ('sandbox', 'production')),
  wompi_public_key      TEXT,
  wompi_integrity_enc   TEXT,
  wompi_events_enc      TEXT,
  updated_at            TEXT NOT NULL
, annual_free_months INTEGER NOT NULL DEFAULT 2, demo_days INTEGER NOT NULL DEFAULT 5, self_signup_enabled INTEGER NOT NULL DEFAULT 1, self_demo_enabled INTEGER NOT NULL DEFAULT 1, max_self_demos INTEGER NOT NULL DEFAULT 30);
